/**
 * TypeScript Compiler Service for Node-RED
 * Handles TypeScript compilation with userDir module resolution
 */

const ts = require("typescript");
const path = require("path");
const fs = require("fs-extra");
const Module = require("module");

class TypeScriptCompiler {
    constructor(userDir) {
        this.userDir = userDir;
        console.log(`[TS-Compiler] Initializing TypeScript compiler for userDir: ${userDir}`);
        
        this.compilerHost = this.createCompilerHost();
        
        // Cache compiled modules
        this.compiledCache = new Map();
        
        // Default library files
        this.defaultLibs = this.loadDefaultLibs();
        
        console.log(`[TS-Compiler] TypeScript compiler initialized`);
    }

    /**
     * Create a custom TypeScript compiler host
     */
    createCompilerHost() {
        console.log('[TS-Compiler] Creating custom compiler host...');
        
        const host = ts.createCompilerHost({
            target: ts.ScriptTarget.ES2020,
            module: ts.ModuleKind.CommonJS,
            moduleResolution: ts.ModuleResolutionKind.NodeJs,
            lib: ['lib.es2020.d.ts'],
            skipLibCheck: true
        });
        
        // Store original methods
        const originalFileExists = host.fileExists;
        const originalReadFile = host.readFile;
        const originalGetSourceFile = host.getSourceFile;
        
        // Override fileExists to check userDir
        host.fileExists = (fileName) => {
            console.log(`[TS-Compiler] Checking if file exists: ${fileName}`);
            
            // Handle virtual function file
            if (fileName === "virtual-function.ts") {
                return true;
            }
            
            // Handle Node-RED types
            if (fileName === 'file:///node-red-types.d.ts') {
                return true;
            }
            
            // Check userDir paths
            if (fileName.includes('@userDir/')) {
                const userDirPath = fileName.replace(/@userDir\//, '');
                const fullPath = path.resolve(this.userDir, userDirPath);
                const exists = fs.existsSync(fullPath);
                console.log(`[TS-Compiler] UserDir file ${fileName} -> ${fullPath} exists: ${exists}`);
                return exists;
            }
            
            const exists = originalFileExists.call(host, fileName);
            console.log(`[TS-Compiler] System file ${fileName} exists: ${exists}`);
            return exists;
        };
        
        // Override readFile to read from userDir
        host.readFile = (fileName) => {
            console.log(`[TS-Compiler] Reading file: ${fileName}`);
            
            // Handle Node-RED types
            if (fileName === 'file:///node-red-types.d.ts') {
                return this.getNodeRedTypes();
            }
            
            // Handle userDir paths
            if (fileName.includes('@userDir/')) {
                const userDirPath = fileName.replace(/@userDir\//, '');
                const fullPath = path.resolve(this.userDir, userDirPath);
                if (fs.existsSync(fullPath)) {
                    const content = fs.readFileSync(fullPath, 'utf8');
                    console.log(`[TS-Compiler] Read userDir file ${fileName} (${content.length} chars)`);
                    return content;
                }
            }
            
            const content = originalReadFile.call(host, fileName);
            if (content) {
                console.log(`[TS-Compiler] Read system file ${fileName} (${content.length} chars)`);
            }
            return content;
        };
        
        // Override getSourceFile for better control
        host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
            console.log(`[TS-Compiler] Getting source file: ${fileName}`);
            
            // Handle virtual function file - return undefined to let TypeScript handle it
            if (fileName === "virtual-function.ts") {
                return undefined;
            }
            
            // Handle userDir imports - for now, ignore them to avoid resolution issues
            if (fileName.includes('@userDir/')) {
                console.log(`[TS-Compiler] Skipping userDir import: ${fileName}`);
                return undefined;
            }
            
            return originalGetSourceFile.call(host, fileName, languageVersion, onError, shouldCreateNewSourceFile);
        };
        
        // Add missing getDefaultLibFileName method
        host.getDefaultLibFileName = (options) => {
            return ts.getDefaultLibFileName(options);
        };
        
        // Simplified module resolution - avoid complex userDir resolution for now
        host.resolveModuleNames = (moduleNames, containingFile, reusedNames, redirectedReference, options) => {
            console.log(`[TS-Compiler] Resolving modules:`, moduleNames, 'from:', containingFile);
            
            const resolvedModules = [];
            
            for (const moduleName of moduleNames) {
                // For @userDir imports, return undefined to avoid resolution issues
                if (moduleName.startsWith('@userDir/')) {
                    console.log(`[TS-Compiler] Skipping userDir module resolution: ${moduleName}`);
                    resolvedModules.push(undefined);
                } else {
                    // Use TypeScript's default resolution for other modules
                    console.log(`[TS-Compiler] Using default resolution for: ${moduleName}`);
                    const result = ts.resolveModuleName(moduleName, containingFile, options, host);
                    resolvedModules.push(result.resolvedModule);
                    
                    if (result.resolvedModule) {
                        console.log(`[TS-Compiler] Resolved ${moduleName} to ${result.resolvedModule.resolvedFileName}`);
                    } else {
                        console.warn(`[TS-Compiler] Failed to resolve module: ${moduleName}`);
                    }
                }
            }
            
            return resolvedModules;
        };
        
        console.log('[TS-Compiler] Custom compiler host created');
        return host;
    }

    /**
     * Get Node-RED type definitions for TypeScript compilation
     */
    getNodeRedTypes() {
        return `
declare global {
    interface NodeMessage {
        payload: any;
        topic?: string;
        _msgid?: string;
        [key: string]: any;
    }

    interface MongoDBChangeEvent {
        collection: string;
        change: "insert" | "update" | "delete" | "replace";
        before: any | null;
        after: any | null;
        changedAt: string;
        metadata?: {
            documentKey?: any;
            updateDescription?: {
                updatedFields?: any;
                removedFields?: string[];
            };
            ns?: {
                db: string;
                coll: string;
            };
        };
    }

    interface NodeSend {
        (msg: NodeMessage | NodeMessage[] | NodeMessage[][]): void;
    }

    interface NodeDone {
        (error?: Error): void;
    }

    interface NodeContext {
        get(key: string): any;
        set(key: string, value: any): void;
        keys(): string[];
        global: {
            get(key: string): any;
            set(key: string, value: any): void;
            keys(): string[];
        };
        flow: {
            get(key: string): any;
            set(key: string, value: any): void;
            keys(): string[];
        };
    }

    interface Node {
        id: string;
        name: string;
        outputCount: number;
        log(...args: any[]): void;
        warn(...args: any[]): void;
        error(...args: any[]): void;
        debug(...args: any[]): void;
        trace(...args: any[]): void;
        status(status: {fill?: string, shape?: string, text?: string}): void;
        send: NodeSend;
        done: NodeDone;
    }

    // Global variables available in TypeScript function nodes
    declare const msg: NodeMessage;
    declare const send: NodeSend;
    declare const done: NodeDone;
    declare const node: Node;
    declare const context: NodeContext;
    declare const flow: NodeContext['flow'];
    declare const global: NodeContext['global'];
    declare const env: { get(key: string): string | undefined };
    
    declare function requireUserDir(module: string): any;
    
    // Node.js globals
    declare const Buffer: typeof globalThis.Buffer;
    declare const console: Console;
    declare const process: Pick<NodeJS.Process, 'env' | 'version' | 'versions' | 'platform' | 'arch'>;
    declare const setTimeout: typeof globalThis.setTimeout;
    declare const clearTimeout: typeof globalThis.clearTimeout;
    declare const setInterval: typeof globalThis.setInterval;
    declare const clearInterval: typeof globalThis.clearInterval;
    declare const setImmediate: typeof globalThis.setImmediate;
    declare const clearImmediate: typeof globalThis.clearImmediate;
}

export {};
        `.trim();
    }

    /**
     * Load TypeScript default library files
     */
    loadDefaultLibs() {
        console.log('[TS-Compiler] Loading default TypeScript libraries...');
        
        const libs = new Map();
        
        try {
            const libPath = path.dirname(require.resolve('typescript'));
            
            // Load essential lib files
            const libFiles = [
                'lib.es5.d.ts',
                'lib.es2015.d.ts',
                'lib.es2020.d.ts',
                'lib.dom.d.ts',
                'lib.webworker.d.ts'
            ];
            
            for (const libFile of libFiles) {
                try {
                    const libFilePath = path.join(libPath, libFile);
                    if (fs.existsSync(libFilePath)) {
                        const content = fs.readFileSync(libFilePath, 'utf8');
                        libs.set(libFile, content);
                        console.log(`[TS-Compiler] Loaded lib: ${libFile}`);
                    }
                } catch (err) {
                    console.warn(`[TS-Compiler] Failed to load TypeScript lib file: ${libFile}`, err.message);
                }
            }
            
            console.log(`[TS-Compiler] Loaded ${libs.size} default libraries`);
        } catch (err) {
            console.error('[TS-Compiler] Failed to load default TypeScript libraries:', err);
        }
        
        return libs;
    }

    /**
     * Compile TypeScript code with proper type checking
     */
    compile(code, options, callback) {
        console.log('[TS-Compiler] Starting TypeScript compilation with type checking...');
        console.log('[TS-Compiler] Code length:', code.length);
        
        try {
            // More strict compilation options for better error detection
            const compilerOptions = {
                target: ts.ScriptTarget.ES2020,
                module: ts.ModuleKind.CommonJS,
                moduleResolution: ts.ModuleResolutionKind.NodeJs,
                esModuleInterop: true,
                allowSyntheticDefaultImports: true,
                strict: false, // Not too strict to avoid overwhelming users
                noImplicitAny: false,
                skipLibCheck: true,
                allowJs: true,
                noEmit: false, // Enable emit to check for more errors
                isolatedModules: false,
                suppressOutputPathCheck: true,
                // Enable more checks
                noUnusedLocals: false, // Don't warn about unused variables
                noUnusedParameters: false,
                noImplicitReturns: false,
                noFallthroughCasesInSwitch: false
            };
            
            console.log('[TS-Compiler] Using type-checking compiler options');
            
            // Create a virtual file system for better type checking
            const fileName = 'function.ts';
            const nodeRedTypesFile = 'file:///node-red-types.d.ts';
            
            const sourceFile = ts.createSourceFile(
                fileName,
                code,
                ts.ScriptTarget.ES2020,
                true
            );
            
            const nodeRedTypesSourceFile = ts.createSourceFile(
                nodeRedTypesFile,
                this.getNodeRedTypes(),
                ts.ScriptTarget.ES2020,
                true
            );
            
            // Create a program for full type checking
            const compilerHost = {
                getSourceFile: (name) => {
                    if (name === fileName) {
                        return sourceFile;
                    }
                    if (name === nodeRedTypesFile) {
                        return nodeRedTypesSourceFile;
                    }
                    // Return undefined for other files to avoid resolution issues
                    return undefined;
                },
                writeFile: () => {}, // No-op
                getCurrentDirectory: () => this.userDir,
                getDirectories: () => [],
                fileExists: (name) => name === fileName || name === nodeRedTypesFile,
                readFile: function(name) {
                    if (name === fileName) return code;
                    if (name === nodeRedTypesFile) return this.getNodeRedTypes();
                    return undefined;
                }.bind(this),
                getCanonicalFileName: (name) => name,
                useCaseSensitiveFileNames: () => true,
                getNewLine: () => '\n',
                getDefaultLibFileName: (options) => {
                    return ts.getDefaultLibFileName(options);
                },
                resolveModuleNames: (moduleNames, containingFile) => {
                    // Custom module resolution
                    return moduleNames.map(moduleName => {
                        if (moduleName.startsWith('@userDir/')) {
                            // Return a placeholder for userDir modules
                            return {
                                resolvedFileName: `${this.userDir}/${moduleName.replace('@userDir/', '')}.ts`,
                                isExternalLibraryImport: false
                            };
                        } else if (['zod', 'lodash', 'date-fns'].includes(moduleName)) {
                            // Known libraries - return placeholder
                            return {
                                resolvedFileName: `node_modules/${moduleName}/index.d.ts`,
                                isExternalLibraryImport: true
                            };
                        } else {
                            // Unknown modules - return undefined to trigger error
                            return undefined;
                        }
                    });
                }
            };
            
            // Create program with our custom host
            const program = ts.createProgram([fileName, nodeRedTypesFile], compilerOptions, compilerHost);
            
            // Get all diagnostics (syntax + semantic)
            const allDiagnostics = [
                ...program.getSyntacticDiagnostics(sourceFile),
                ...program.getSemanticDiagnostics(sourceFile)
            ];
            
            console.log(`[TS-Compiler] Found ${allDiagnostics.length} diagnostics`);
            
            // Process diagnostics into errors and warnings
            const errors = [];
            const warnings = [];
            
            allDiagnostics.forEach(diagnostic => {
                const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
                const position = diagnostic.start ? 
                    ts.getLineAndCharacterOfPosition(sourceFile, diagnostic.start) : 
                    { line: 0, character: 0 };
                
                const diagnosticInfo = {
                    line: position.line + 1,
                    column: position.character + 1,
                    message: message,
                    code: diagnostic.code,
                    severity: diagnostic.category
                };
                
                // Categorize by severity
                if (diagnostic.category === ts.DiagnosticCategory.Error) {
                    // Filter out some module resolution errors that are expected
                    if (diagnostic.code === 2307 && message.includes('@userDir/')) {
                        // Convert @userDir module errors to warnings
                        warnings.push({...diagnosticInfo, message: `UserDir import warning: ${message}`});
                    } else if (diagnostic.code === 2304) {
                        // Cannot find name errors (like undefined variables)
                        errors.push(diagnosticInfo);
                    } else if (diagnostic.code === 2552 || diagnostic.code === 2304) {
                        // Cannot find name or undefined variable
                        errors.push(diagnosticInfo);
                    } else if (!message.includes('node_modules') && !message.includes('lib.d.ts')) {
                        // Other errors that aren't library-related
                        errors.push(diagnosticInfo);
                    }
                } else if (diagnostic.category === ts.DiagnosticCategory.Warning) {
                    warnings.push(diagnosticInfo);
                }
            });
            
            // Generate JavaScript output even if there are errors (for runtime)
            let outputText = '';
            try {
                const transpileResult = ts.transpileModule(code, {
                    compilerOptions: compilerOptions,
                    moduleName: 'functionNode'
                });
                outputText = transpileResult.outputText || '';
            } catch (transpileError) {
                console.error('[TS-Compiler] Transpilation error:', transpileError);
                outputText = code; // Fallback to original code
            }
            
            const compilationResult = {
                outputText: outputText,
                errors: errors,
                warnings: warnings.length,
                success: errors.length === 0
            };
            
            console.log('[TS-Compiler] Compilation result:', {
                success: compilationResult.success,
                outputLength: compilationResult.outputText.length,
                errorCount: compilationResult.errors.length,
                warningCount: compilationResult.warnings
            });
            
            if (errors.length > 0) {
                console.log('[TS-Compiler] Errors found:', errors);
            }
            
            callback(null, compilationResult);
            
        } catch (error) {
            console.error('[TS-Compiler] Compilation error:', error);
            
            const fallbackResult = {
                outputText: code,
                errors: [{
                    line: 1,
                    column: 1,
                    message: `TypeScript compilation failed: ${error.message}`,
                    code: 0,
                    severity: ts.DiagnosticCategory.Error
                }],
                warnings: 0,
                success: false
            };
            
            callback(null, fallbackResult);
        }
    }

    /**
     * Get available types in userDir
     */
    getAvailableTypes(callback) {
        console.log('[TS-Compiler] Getting available types...');
        
        try {
            const types = {
                userDirModules: [],
                installedPackages: []
            };
            
            // Scan userDir for TypeScript files
            const scanDir = (dir, prefix = '') => {
                if (!fs.existsSync(dir)) {
                    console.log(`[TS-Compiler] Directory does not exist: ${dir}`);
                    return;
                }
                
                console.log(`[TS-Compiler] Scanning directory: ${dir}`);
                
                const files = fs.readdirSync(dir);
                for (const file of files) {
                    const fullPath = path.join(dir, file);
                    const stat = fs.statSync(fullPath);
                    
                    if (stat.isDirectory() && !file.startsWith('.') && file !== 'node_modules') {
                        scanDir(fullPath, prefix + file + '/');
                    } else if (file.endsWith('.ts') || file.endsWith('.tsx')) {
                        const modulePath = '@userDir/' + prefix + file.replace(/\.(ts|tsx)$/, '');
                        types.userDirModules.push({
                            path: modulePath,
                            file: fullPath
                        });
                        console.log(`[TS-Compiler] Found TypeScript module: ${modulePath}`);
                    }
                }
            };
            
            scanDir(this.userDir);
            
            // Check for installed @types packages
            const nodeModulesPath = path.join(this.userDir, 'node_modules', '@types');
            if (fs.existsSync(nodeModulesPath)) {
                const typePackages = fs.readdirSync(nodeModulesPath);
                types.installedPackages = typePackages.map(pkg => '@types/' + pkg);
                console.log(`[TS-Compiler] Found ${types.installedPackages.length} @types packages`);
            }
            
            console.log(`[TS-Compiler] Available types: ${types.userDirModules.length} userDir modules, ${types.installedPackages.length} installed packages`);
            
            callback(null, types);
        } catch (error) {
            console.error('[TS-Compiler] Error getting available types:', error);
            callback(error);
        }
    }

    /**
     * Watch userDir for changes
     */
    watchUserDir(onChange) {
        console.log(`[TS-Compiler] Starting to watch userDir: ${this.userDir}`);
        
        const watcher = fs.watch(this.userDir, { recursive: true }, (eventType, filename) => {
            if (filename && (filename.endsWith('.ts') || filename.endsWith('.tsx'))) {
                console.log(`[TS-Compiler] File changed: ${filename} (${eventType})`);
                
                // Clear cache for changed file
                this.compiledCache.delete(filename);
                onChange(eventType, filename);
            }
        });
        
        return watcher;
    }
}

module.exports = TypeScriptCompiler;